static long fact(int n) {
    if (n == 0) return 1;
    long f = fact(n - 1);
    long r = 0;
    for (long i = 0; i < f; i++) r += n;   // adds n, (n-1)! times
    return r;
}

void h(long n) {
    if (n <= 2) return;
    for (long i = n; i > 1; i /= 2) work();
    h((long) Math.sqrt(n));
    h((long) Math.sqrt(n));
}

void pw(int n) {
    if (n <= 1) return;
    if (n % 2 == 0) pw(n / 2);
    else { for (int i = 0; i < n; i++) work(); pw(n - 1); }
}

static int f(int[] a) {                // a has length N
    Set<Integer> seen = new HashSet<>();
    TreeSet<Integer> big = new TreeSet<>();
    int count = 0;
    for (int x : a) {
        if (seen.contains(x)) count++;
        seen.add(x);
        big.add(x);
        if (big.size() > 10) big.pollFirst();
    }
    return count;
}

static int mulch(int[] a) {
    int n = a.length;
    if (n <= 1) return 1;
    int[] left = Arrays.copyOfRange(a, 0, n / 2);
    int[] right = Arrays.copyOfRange(a, n / 2, n);
    return mulch(left) + mulch(right) + mulch(left);
}
